", "content": [{"type": "text", "text": "中途效率变化时忘记分段"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "合作效率和单独效率搞混"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "合作工程是高频考点，重点练习同时合作和轮流合作两种题型。"}]}]}]}$$ AS jsonb), NULL, '数量关系-工程问题-合作工程的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "工程问题", "合作工程"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_coop", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
